## Integration Examples

### C# (.NET)

```csharp
using System.Net.Http.Json;

public class PackageClient
{
    private readonly HttpClient _http;

    public PackageClient(HttpClient http)
    {
        _http = http;
    }

    public async Task<List<Package>> GetPackagesAsync(string appId, string? os = null, string? arch = null)
    {
        var url = $"/api/applications/{appId}/packages";
        var queryParams = new List<string>();

        if (!string.IsNullOrEmpty(os)) queryParams.Add($"os={os}");
        if (!string.IsNullOrEmpty(arch)) queryParams.Add($"arch={arch}");

        if (queryParams.Count > 0)
            url += "?" + string.Join("&", queryParams);

        return await _http.GetFromJsonAsync<List<Package>>(url);
    }

    public async Task<Package?> GetPackageAsync(string appId, string packageId)
    {
        return await _http.GetFromJsonAsync<Package>(
            $"/api/applications/{appId}/packages/{packageId}");
    }

    public async Task DownloadPackageAsync(string appId, string packageId, string? version, string outputPath)
    {
        var url = $"/api/applications/{appId}/packages/{packageId}/download";
        if (!string.IsNullOrEmpty(version))
            url += $"?version={version}";

        var bytes = await _http.GetByteArrayAsync(url);
        await File.WriteAllBytesAsync(outputPath, bytes);
    }
}

// Usage
var client = new PackageClient(new HttpClient());

// Discover packages for Linux x64
var packages = await client.GetPackagesAsync("my-app-id", os: "linux", arch: "x64");

// Get specific package
var plugin = await client.GetPackageAsync("my-app-id", "my-plugin");

// Download latest version
await client.DownloadPackageAsync("my-app-id", "my-plugin", null, "plugin.zip");

// Download specific version
await client.DownloadPackageAsync("my-app-id", "my-plugin", "1.0.0", "plugin-1.0.0.zip");
```

### JavaScript / TypeScript

```typescript
const BASE_URL = 'https://api.example.com';

interface PackageVersion {
  version: string;
  sizeBytes: number;
  contentHash: string;
  createdAt: string;
  releaseNotes: string | null;
}

interface Package {
  id: string;
  packageId: string;
  title: string;
  description: string | null;
  supportedOperatingSystems: string[];
  supportedArchitectures: string[];
  hasIcon: boolean;
  latestVersion: string | null;
  versions: PackageVersion[];
}

async function getPackages(appId: string, filters?: { os?: string; arch?: string }): Promise<Package[]> {
  const params = new URLSearchParams();
  if (filters?.os) params.set('os', filters.os);
  if (filters?.arch) params.set('arch', filters.arch);

  const url = `${BASE_URL}/api/applications/${appId}/packages${params.toString() ? '?' + params : ''}`;
  const response = await fetch(url);
  return response.json();
}

async function getPackage(appId: string, packageId: string): Promise<Package> {
  const response = await fetch(`${BASE_URL}/api/applications/${appId}/packages/${packageId}`);
  return response.json();
}

async function downloadPackage(appId: string, packageId: string, version?: string): Promise<Blob> {
  const url = version 
    ? `${BASE_URL}/api/applications/${appId}/packages/${packageId}/download?version=${version}`
    : `${BASE_URL}/api/applications/${appId}/packages/${packageId}/download`;

  const response = await fetch(url);
  return response.blob();
}

// Usage
const packages = await getPackages('my-app-id', { os: 'linux', arch: 'x64' });
const plugin = await getPackage('my-app-id', 'my-plugin');
const zipBlob = await downloadPackage('my-app-id', 'my-plugin', '1.0.0');
```

### Python

```python
import requests
from dataclasses import dataclass
from typing import Optional, List
from datetime import datetime

@dataclass
class PackageVersion:
    version: str
    size_bytes: int
    content_hash: Optional[str]
    created_at: datetime
    release_notes: Optional[str]

@dataclass
class Package:
    id: str
    package_id: str
    title: str
    description: Optional[str]
    supported_operating_systems: List[str]
    supported_architectures: List[str]
    has_icon: bool
    latest_version: Optional[str]
    versions: List[PackageVersion]

class PackageClient:
    def __init__(self, base_url: str):
        self.base_url = base_url.rstrip('/')

    def get_packages(self, app_id: str, os: Optional[str] = None, arch: Optional[str] = None) -> List[dict]:
        params = {}
        if os:
            params['os'] = os
        if arch:
            params['arch'] = arch

        response = requests.get(
            f"{self.base_url}/api/applications/{app_id}/packages",
            params=params
        )
        return response.json()

    def get_package(self, app_id: str, package_id: str) -> dict:
        response = requests.get(
            f"{self.base_url}/api/applications/{app_id}/packages/{package_id}"
        )
        return response.json()

    def download_package(self, app_id: str, package_id: str, version: Optional[str] = None) -> bytes:
        params = {'version': version} if version else {}
        response = requests.get(
            f"{self.base_url}/api/applications/{app_id}/packages/{package_id}/download",
            params=params
        )
        return response.content

# Usage
client = PackageClient("https://api.example.com")
packages = client.get_packages("my-app-id", os="linux", arch="x64")
plugin = client.get_package("my-app-id", "my-plugin")
zip_bytes = client.download_package("my-app-id", "my-plugin", "1.0.0")
```

